struct RenderFullScalarDiagnostic
{
	LabelScalarPublicationCensusCaptureWitness capture;
	LabelPublicationSnapshot first_label, native_label;
	const char* first_reason = nullptr;
	const char* stage = nullptr;
	uint32_t state_count = 0, scalar_count = 0, native_queries = 0;
	bool capture_attempted = false, prepare_attempted = false;
	bool native_checked = false, native_completed = false, emitted = false;
	void Refuse(const char* value, const char* at, const LabelPublicationSnapshot* label = nullptr)
	{
		if (first_reason != nullptr) return;
		first_reason = value; stage = at;
		if (label != nullptr) first_label = *label;
	}
};
static_assert(sizeof(RenderFullScalarDiagnostic) <= 640);

struct RenderFullScalarCompletionBank
{
	LabelScalarPublicationCensusBank census;
	GpuMemoryRecordingIdentity origin;
	CommandBuffer* original_buffer = nullptr;
	RenderFullScalarDiagnostic diagnostic;
	bool attempted = false;
	bool qualified = false;
	bool pending_current = false, current_activated = false;
	uint64_t metadata_bytes = 0;
};
static_assert(sizeof(RenderFullScalarCompletionBank) < LabelScalarPublicationCensusBank::MaxCombinedRetainedMetadataBytes);

[[maybe_unused]] static uint64_t RenderFullRetainedScalarBytes(const RenderFullScalarCompletionBank* bank)
{
	return bank != nullptr ? sizeof(*bank) + bank->census.RetainedMetadataBytes() : 0;
}

[[maybe_unused]] static void ReportRenderFullScalarOriginal(RenderFullScalarCompletionBank* bank, const char* terminal_reason)
{
	if (bank == nullptr || bank->diagnostic.emitted) return;
	bank->diagnostic.emitted = true;
	const auto& diagnostic = bank->diagnostic;
	const auto& origin = bank->origin;
	const auto& label = diagnostic.first_label;
	const auto& native = diagnostic.native_label;
	const auto& capture = diagnostic.capture;
	std::fprintf(stderr, "[GFX_RENDER_FULL_SCALAR_ORIGINAL] terminal_reason=%s first_reason=%s stage=%s"
	    " origin_cp=%p origin_queue=%d origin_epoch=%" PRIu64 " origin_serial=%" PRIu64 " origin_recording=%" PRIu64
	    " begin_submit_cutoff=%" PRIu64 " begin_completed_cutoff=%" PRIu64
	    " attempted=%u qualified=%u pending_current=%u current_activated=%u capture_attempted=%u capture_complete=%u discovery_complete=%u prepare_attempted=%u"
	    " states=%u scalars=%u native_queries=%u native_checked=%u native_completed=%u"
	    " rejected_instance=%" PRIu64 " rejected_serial=%" PRIu64 " rejected_queued=%" PRIu64
	    " rejected_completed=%" PRIu64 " rejected_pending=%" PRIu64
	    " native_instance=%" PRIu64 " native_serial=%" PRIu64 " metadata_bytes=%" PRIu64
	    " diagnostic_bytes=%zu capsule_bytes=%zu capture_before_effects=1 native_receipt=original metadata_only=1 guest_reads=0"
	    " diagnostic_queries=0 recapture=0 authority=unchanged\n",
	    terminal_reason != nullptr ? terminal_reason : "unreported", diagnostic.first_reason != nullptr ? diagnostic.first_reason : "none",
	    diagnostic.stage != nullptr ? diagnostic.stage : "none", static_cast<void*>(origin.cp), origin.queue,
	    origin.submission_session_epoch, origin.recording_submit_serial, origin.recording_id,
	    origin.begin_submit_serial_cutoff, origin.begin_completed_serial_cutoff, bank->attempted ? 1u : 0u,
	    bank->qualified ? 1u : 0u, bank->pending_current ? 1u : 0u, bank->current_activated ? 1u : 0u,
	    diagnostic.capture_attempted ? 1u : 0u, capture.complete ? 1u : 0u,
	    capture.discovery_complete ? 1u : 0u, diagnostic.prepare_attempted ? 1u : 0u,
	    diagnostic.state_count, diagnostic.scalar_count, diagnostic.native_queries,
	    diagnostic.native_checked ? 1u : 0u, diagnostic.native_completed ? 1u : 0u,
	    label.instance_id, label.submit_serial, label.queued, label.completed, label.pending,
	    native.instance_id, native.submit_serial, bank->metadata_bytes, sizeof(RenderFullScalarDiagnostic), sizeof(*bank));
	if (!capture.row_present) return;
	const auto& observed = capture.original;
	const auto& enrolled = capture.delivery_enrollment;
	const auto& registered = capture.registered;
	std::fprintf(stderr, "[GFX_RENDER_FULL_SCALAR_CAPTURE_ROW] reason=%s row=%u states_discovered=%u scalars_qualified_prefix=%u"
	    " key=%p publication=%016" PRIx64 " instance=%" PRIu64 " cp=%p queue=%d epoch=%" PRIu64 " serial=%" PRIu64
	    " queued=%" PRIu64 " completed=%" PRIu64 " cancelled=%" PRIu64 " pending=%" PRIu64 " ambiguous=%u"
	    " frozen_instance=%" PRIu64 " frozen_cp=%p frozen_queue=%d frozen_epoch=%" PRIu64 " frozen_serial=%" PRIu64
	    " frozen_queued=%" PRIu64 " frozen_completed=%" PRIu64 " frozen_cancelled=%" PRIu64 " frozen_pending=%" PRIu64
	    " frozen_ambiguous=%u sequence=%" PRIu64 " destination=%016" PRIx64 " bytes=%" PRIu64 " generation=%" PRIu64
	    " callback_1=%016" PRIx64 " callback_2=%016" PRIx64 " role=%" PRIu64
	    " sealed_checked=%u sealed=%u describe_checked=%u described=%u seal_checked=%u seal_equal=%u enrollment_checked=%u enrollment_equal=%u"
	    " original_pass=1 metadata_only=1 guest_reads=0 diagnostic_queries=0\n",
	    capture.reason != nullptr ? capture.reason : "none", capture.row_index, capture.state_count, capture.scalar_count,
	    static_cast<void*>(capture.key), capture.publication_identity, observed.instance_id, static_cast<void*>(observed.cp), observed.queue,
	    observed.session_epoch, observed.submit_serial, observed.queued, observed.completed, observed.cancelled, observed.pending,
	    observed.identity_ambiguous ? 1u : 0u, enrolled.instance_id, static_cast<void*>(enrolled.cp), enrolled.queue,
	    enrolled.session_epoch, enrolled.submit_serial, enrolled.queued, enrolled.completed, enrolled.cancelled, enrolled.pending,
	    enrolled.identity_ambiguous ? 1u : 0u, registered.registered_sequence, registered.registered_destination,
	    registered.registered_write_bytes, registered.registered_destination_generation, registered.registered_callback_1,
	    registered.registered_callback_2, registered.registered_preparation_role, capture.sealed_checked ? 1u : 0u, capture.sealed ? 1u : 0u,
	    capture.description_checked ? 1u : 0u, capture.described ? 1u : 0u, capture.seal_checked ? 1u : 0u,
	    capture.seal_equal ? 1u : 0u, capture.enrollment_checked ? 1u : 0u, capture.enrollment_equal ? 1u : 0u);
}

static bool RenderFullScalarLeaseUnavailable(const char* reason)
{
	return reason != nullptr && std::strcmp(reason, "lease-acquisition-retry-exhausted") == 0;
}

static bool ResourceProofSingleRangeInsideHeap(uint64_t address, uint64_t bytes, uint64_t heap_address, uint64_t heap_bytes)
{
	if (address == 0 || bytes == 0 || bytes > UINT64_MAX - address || heap_address == 0 || heap_bytes == 0 ||
	    heap_bytes > UINT64_MAX - heap_address || address < heap_address) return false;
	const uint64_t offset = address - heap_address;
	return offset < heap_bytes && bytes <= heap_bytes - offset;
}

