		bool                         read_only                     = false;
		bool                         check_hash                    = false;
		bool                         eop_recheck_guest             = false;
		// Set when a virtual EOP publication exported this VideoOut buffer and
		// recorded its content hash; every later pin must still prove that the
		// guest bytes were not edited since that export. The proof is scoped to
		// this block: unrelated VM activity is not evidence of a guest edit.
		bool                         eop_videoout_pinned           = false;
		bool                         mip_snapshot                  = false;
		bool                         guest_texture_origin          = false;
		// Factory provenance is fail-closed and belongs to this host lifetime.
		// A later upload never turns an unknown creator into a canonical source.
		bool                         guest_source_creation_known   = false;
		VulkanMemory                 mem;
		GpuMemoryPinnedLifetimeState* pinned_lifetime              = nullptr;
		bool                         render_target_snapshot        = false;
