		// Checked at the lifetime's mutation boundary and again on candidate use.
		bool backing_valid = false;
		// Full immutable block and physical aliases were enrolled for CPU reads.
		// Enrollment lasts until owner retirement; it is not a dirty-byte proof.
		bool read_guards_enrolled = false;
		uint64_t handoff_guard_owner = 0;
		std::array<std::vector<Core::VirtualMemory::GuestBackingSpan>, VADDR_BLOCKS_MAX> backing;
		std::array<MemoryHandoffIntervals, VADDR_BLOCKS_MAX> dirty;
		GpuMemoryRecordingIdentity producer;
		GpuMemoryRecordingIdentity latest_access;
		GpuMemoryAccessKind latest_kind = GpuMemoryAccessKind::Unknown;
		std::vector<GpuMemoryRecordingIdentity> readers;
		bool producer_ambiguous = false;
		bool access_ambiguous = false;
		bool producer_host_visible = false;
		bool gpu_alias_stale = false;
		uint64_t cpu_write_epoch = 0;
		uint64_t cpu_upload_epoch = 0;
		// Independent of the optional content ledger. Every possible native
		// write, copy or upload advances it, even within the same recording.
		uint64_t native_readback_epoch = 0;
