struct EopSnapshotReserveCounts
{
	uint32_t read_only = 0, writable = 0, colors = 0, families = 0, guest_sources = 0;
};

static bool ResourceProofCountSnapshotObject(EopSnapshotReserveCounts* counts, GpuMemoryObjectType type,
    bool read_only, bool sampled_family, UniformDepthZeroRole uniform_role)
{
	if (counts == nullptr) return false;
	// These are route counts, not resource qualification. Protected depth and
	// sampled family members retain their original dedicated proofs below.
	if (uniform_role == UniformDepthZeroRole::MetadataSource || uniform_role == UniformDepthZeroRole::Snapshot ||
	    (type == GpuMemoryObjectType::Texture && sampled_family)) return true;
	const auto add = [](uint32_t* count) {
		if (*count == ResourceProofLimits::MaxLiveObjects) return false;
		++*count;
		return true;
	};
	switch (type)
	{
		case GpuMemoryObjectType::VertexBuffer:
		case GpuMemoryObjectType::IndexBuffer:
		case GpuMemoryObjectType::Texture: return add(&counts->guest_sources);
		case GpuMemoryObjectType::StorageBuffer: return add(read_only ? &counts->read_only : &counts->writable);
		case GpuMemoryObjectType::RenderTexture: return add(&counts->colors) && add(&counts->families);
		default: return true;
	}
}

template <typename T>
static bool ResourceProofPrechargeSnapshotPlan(uint32_t count, uint64_t* metadata_bytes)
{
	if (count > ResourceProofLimits::MaxLiveObjects) return false;
	// Empty Core::SimpleArray::Expand(count) reserves count+1 slots. Charge
	// every category before any of the five vectors allocates or copies.
	return ResourceProofAccumulate(count == 0 ? 0 : (uint64_t(count) + 1u) * sizeof(T),
	    ResourceProofLimits::MaxLogicalMetadataBytes, metadata_bytes);
}

template <typename T>
static bool ResourceProofReserveSnapshotPlan(Vector<T>* values, uint32_t count)
{
	if (values == nullptr || values->Size() != 0 || values->Capacity() != 0 || count > ResourceProofLimits::MaxLiveObjects) return false;
	if (count == 0) return true;
	values->Expand(count);
	return values->Capacity() == count + 1u;
}

template <typename T>
static bool ResourceProofReserveSnapshotAppend(Vector<T>* values, uint32_t planned_count, uint64_t retained_relations,
    uint64_t* metadata_bytes, uint64_t* relations)
{
	if (values == nullptr || metadata_bytes == nullptr || relations == nullptr ||
	    planned_count > ResourceProofLimits::MaxLiveObjects || values->Size() >= planned_count ||
	    values->Capacity() != planned_count + 1u) return false;
	// Add's equality-triggered expansion cannot run: even the final planned
	// element has new_size < capacity. Unplanned appends never grow a vector.
	uint64_t bytes = *metadata_bytes, links = *relations;
	if (!ResourceProofAccumulate(retained_relations, ResourceProofLimits::MaxLinks, &links) ||
	    !ResourceProofAccumulate(retained_relations * sizeof(std::pair<OverlapType, int>),
	        ResourceProofLimits::MaxLogicalMetadataBytes, &bytes)) return false;
	*metadata_bytes = bytes;
	*relations = links;
	return true;
}

