	source.info.mem = render_host.memory; sampled.info.mem = copy_host.memory;
	source.info.access.lifetime_generation = 1; sampled.info.access.lifetime_generation = 2;
	source.info.guest_source_creation_known = true; sampled.info.render_target_snapshot = true;
