	source.info.update_with_buffer_func = render.GetUpdateWithBufferFunc();
	sampled.info.delete_func = texture.GetDeleteFunc(); sampled.info.update_func = texture.GetUpdateFunc();
	sampled.info.update_with_buffer_func = texture.GetUpdateWithBufferFunc();
	uint64_t next_epoch = 0;
	GpuMemoryRecordAccess(&source.info.access, identity, GpuMemoryAccessKind::ColorAttachmentReadWrite, false);
	GpuMemoryRecordAccess(&source.info.access, identity, GpuMemoryAccessKind::ColorAttachmentReadWrite, true);
	GpuMemoryRecordContentMutation(&source.info.content, &next_epoch, identity, GpuMemoryContentMutationKind::ColorAttachmentWrite);
	identity.command_ordinal = 2;
	GpuMemoryRecordAccess(&source.info.access, identity, GpuMemoryAccessKind::TransferRead, true);
	GpuMemoryRecordAccess(&sampled.info.access, identity, GpuMemoryAccessKind::SampledRead, false);
	GpuMemoryRecordAccess(&sampled.info.access, identity, GpuMemoryAccessKind::TransferWrite, true);
