void GpuMemoryFree(GraphicContext* ctx, CommandBuffer* buffer, uint64_t vaddr, uint64_t size, bool unmap)
{
	EXIT_IF(g_gpu_memory == nullptr);
	EXIT_IF(ctx == nullptr);

	// Explicit VM owner cleanup also arrives directly from Kernel, after its
	// GPU drain and committed backing retirement. Keep the renderer before
	// tracker ordering even when there is no command processor caller.
	auto* renderer = unmap ? GraphicsRenderMemoryMutex() : nullptr;
	if (renderer != nullptr) renderer->Lock();
	g_gpu_memory->Free(ctx, buffer, vaddr, size, unmap);
	if (renderer != nullptr) renderer->Unlock();
}

