GpuMemoryRenderFullWriteBackResult GpuMemory::TryWriteBackRenderFull(GraphicContext* ctx, CommandProcessor* cp,
    GpuMemoryRenderFullPreflightTicket* ticket, bool exclusive_stream)
{
	if (ctx == nullptr || cp == nullptr || ticket == nullptr) return {false, false, "render-full-input-invalid"};
#if LUMEN_PLATFORM == LUMEN_PLATFORM_OSX
	if (ticket->m_generation == UINT64_MAX) return {false, false, "mapping-generation-unavailable"};
	auto* current_buffer = GraphicsRunCommandProcessorGetCurrentBuffer(cp);
	const auto current = GpuMemoryGetRecordingIdentity(current_buffer,
	    current_buffer != nullptr ? current_buffer->GetTrackedCommandOrdinal() : 0);
	if (!ticket->m_state)
	{
		// Both the VM token and the complete recording identity precede the
		// first attempt. A refusal never enrolls a newer recording or token.
		ticket->m_state = std::make_shared<GpuMemoryRenderFullPreflightState>();
		ticket->m_state->recording = current;
	}
	auto& retained = *ticket->m_state;
	if (!CpuProofRecordingEqual(retained.recording, current)) return {false, false, "render-full-recording-changed"};
	if (retained.scalars.attempted && retained.scalars.original_buffer != current_buffer)
		return {false, false, "render-full-original-buffer-changed"};
	// Keep the original inventory stable from validation through the attempt
	// and its first-failure capture. A raw tracker mutator must not enter a gap
	// between these boundaries. This recursive level also unwinds on return.
	Core::LockGuard tracker_lock(m_mutex);
	const bool resume_allowed = exclusive_stream && GraphicsRenderRenderFullCpuScopeValid(cp) &&
	    GraphicsRunCommandProcessorExclusiveRecordingValid(cp, current_buffer);
	if (!retained.scalars.attempted)
	{
		// Enroll once, before WriteBack can start any effects. A failed or
		// unavailable census leaves the existing strict path in place forever
		// for this ticket; later CPU gaps cannot acquire fresh scalar authority.
		retained.scalars.attempted = true;
		retained.scalars.origin = retained.recording;
		retained.scalars.original_buffer = current_buffer;
		if (resume_allowed)
		{
			LabelScalarPublicationCensusBank census;
			const char* census_reason = nullptr;
			retained.scalars.diagnostic.capture_attempted = true;
			if (LabelCaptureScalarPublicationCensusBank(&census, &census_reason,
			        LabelScalarPublicationCensusBank::MaxCombinedRetainedMetadataBytes - sizeof(retained.scalars) - ResourceProofInventoryScratchBytes,
			        &retained.scalars.diagnostic.capture))
				PrepareRenderFullScalarBank(&retained.scalars, retained.recording, census,
				    [](CommandProcessor* owner, int queue, uint64_t epoch, uint64_t serial) {
					    return GraphicsRunCommandProcessorCompleted(owner, queue, epoch, serial);
				    });
			else
			{
				retained.scalars.diagnostic.state_count = retained.scalars.diagnostic.capture.state_count;
				retained.scalars.diagnostic.scalar_count = retained.scalars.diagnostic.capture.scalar_count;
				retained.scalars.diagnostic.Refuse(census_reason != nullptr ? census_reason : "scalar-census-unreported",
				    "capture-before-effects", retained.scalars.diagnostic.capture.row_present ?
				        &retained.scalars.diagnostic.capture.original : nullptr);
			}
		}
		else retained.scalars.diagnostic.Refuse("render-full-scalar-scope-unavailable", "scope-before-effects");
	}
	const auto* scalar_bank = retained.scalars.qualified ? &retained.scalars : nullptr;
	if (scalar_bank != nullptr || retained.scalars.pending_current)
	{
		if (!resume_allowed || !CpuProofRecordingEqual(retained.scalars.origin, retained.recording))
			return {false, false, "render-full-scalar-original-scope-changed"};
		const char* scalar_reason = scalar_bank != nullptr ? RenderFullScalarBankRejection(*scalar_bank) :
		    RenderFullPendingCurrentScalarBankRejection(retained.scalars);
		if (scalar_reason != nullptr)
		{
			if (!RenderFullScalarLeaseUnavailable(scalar_reason)) return {false, false, scalar_reason};
			if (!retained.inventory_captured)
			{
				if (!CaptureCpuProofInventory(&retained.inventory, cp, nullptr,
				        CpuProofInventoryMode::RenderFullPreflightCompletionTickets, &retained.recording, scalar_bank,
				        scalar_bank != nullptr, scalar_bank == nullptr ? RenderFullRetainedScalarBytes(&retained.scalars) : 0))
					return {false, false, "render-full-inventory-unqualified"};
				retained.inventory_captured = true;
			}
			const auto continuation = ValidateRenderFullPreflightContinuation(retained.inventory, ticket->m_generation, scalar_bank != nullptr);
			if (!continuation.complete)
				return continuation.retryable && RenderFullScalarLeaseUnavailable(continuation.reason)
				    ? GpuMemoryRenderFullWriteBackResult {false, true, "render-full-scalar-census-lease-unavailable"} : continuation;
		}
	}
	if (retained.inventory_captured)
	{
		if (!exclusive_stream || !GraphicsRunCommandProcessorExclusiveRecordingValid(cp, current_buffer))
			return {false, false, "render-full-stream-not-exclusive"};
		const auto continuation = ValidateRenderFullPreflightContinuation(retained.inventory, ticket->m_generation,
		    scalar_bank != nullptr && resume_allowed);
		if (!continuation.complete) return continuation;
	}
	const char* retry_reason = nullptr;
	const auto scalar_metadata_bytes = RenderFullRetainedScalarBytes(&retained.scalars);
	const uint64_t shared_scratch = ResourceProofInventoryScratchBytes;
	if (retained.inventory_captured && retained.inventory.metadata_bytes < scalar_metadata_bytes + shared_scratch)
		return {false, false, "render-full-retained-metadata-accounting-changed"};
	const uint64_t retained_inventory_bytes = retained.inventory_captured ? retained.inventory.metadata_bytes - scalar_metadata_bytes - shared_scratch : 0;
	const RenderFullWriteBackResumeScope resume {current, &retained.scalars, retained.scalars.original_buffer, retained_inventory_bytes};
	const bool complete = WriteBack(ctx, cp, 0, UINT64_MAX, GpuMemoryCpuCopyRole::None, ticket->m_generation, &retry_reason,
	    nullptr, "render-full", nullptr, resume_allowed ? &resume : nullptr);
	const auto attempt = RenderFullWriteBackAttemptDecision(complete, retry_reason);
	// WriteBack sets this output only for exact acquisition exhaustion before
	// its first flush/command/fence/callback. All later failures remain final.
	if (attempt.complete || !attempt.retryable)
	{
		if (!attempt.complete) ReportRenderFullScalarOriginal(&retained.scalars, attempt.reason);
		return attempt;
	}
	if (!exclusive_stream || retained.recording.cp != cp || retained.recording.recording_id == 0 ||
	    !GraphicsRunCommandProcessorExclusiveRecordingValid(cp, current_buffer))
		return {false, false, "render-full-stream-not-exclusive"};
	if (!retained.inventory_captured)
	{
		auto* after_buffer = GraphicsRunCommandProcessorGetCurrentBuffer(cp);
		const auto after = GpuMemoryGetRecordingIdentity(after_buffer,
		    after_buffer != nullptr ? after_buffer->GetTrackedCommandOrdinal() : 0);
		if (!CpuProofRecordingEqual(retained.recording, after)) return {false, false, "render-full-recording-changed"};
		if (!CaptureCpuProofInventory(&retained.inventory, cp, nullptr,
		        CpuProofInventoryMode::RenderFullPreflightCompletionTickets, &retained.recording, scalar_bank, scalar_bank != nullptr,
		        scalar_bank == nullptr ? RenderFullRetainedScalarBytes(&retained.scalars) : 0))
			return {false, false, "render-full-inventory-unqualified"};
		retained.inventory_captured = true;
	}
	return attempt;
#else
	// These backends cannot supply the managed lease continuation capability.
	(void)exclusive_stream;
	return {WriteBack(ctx, cp, 0, UINT64_MAX, GpuMemoryCpuCopyRole::None, UINT64_MAX, nullptr, nullptr, "render-full"),
	    false, "render-full-ordinary-writeback"};
#endif
}

GpuMemoryRenderFullWriteBackResult GpuMemoryTryWriteBackRenderFull(GraphicContext* ctx, CommandProcessor* cp,
    GpuMemoryRenderFullPreflightTicket* ticket, bool exclusive_stream)
{
	if (g_gpu_memory == nullptr) return {false, false, "resource-tracker-unavailable"};
	return g_gpu_memory->TryWriteBackRenderFull(ctx, cp, ticket, exclusive_stream);
}

void GpuMemoryWriteBack(GraphicContext* ctx, CommandProcessor* cp, const char* origin)
{
	// Fence callbacks have already completed their native prefix. CPU consumers
	// now publish their own byte dependencies, so an EOP signal need not drain
	// independent native resources merely to make that signal visible.
	if (GpuMemoryCpuHandoffEnabled()) return;
	EXIT_IF(g_gpu_memory == nullptr);
	EXIT_IF(ctx == nullptr);

	// Only the worker's exact callback1 witness admits this pure depth proof.
	// The common member entry rejects nested acquisition from every overload.
	const auto* label_scope = LabelGetActiveWriteBackProofScope(cp);
	// update CPU memory after GPU-drawing
	EXIT_IF(!g_gpu_memory->WriteBack(ctx, cp, 0, UINT64_MAX, GpuMemoryCpuCopyRole::None,
	    UINT64_MAX, nullptr, nullptr, origin, label_scope));
}

