void GpuMemoryTraceEopResources(CommandProcessor* cp, uint32_t packet, uint32_t event_control, uint32_t address_control)
{
	if (!GpuMemoryEopResourceTraceEnabled()) return;
	// Only control bits are printed, before the unchanged terminal diagnostic.
	std::fprintf(stderr, "[GFX_EOP_RESOURCE_TRACE_BEGIN] packet=%08x event=%08x address_control=%08x\n",
	             packet, event_control, address_control & 0xffff0000u);
	if (g_gpu_memory == nullptr || cp == nullptr)
	{
		std::fprintf(stderr, "[GFX_EOP_RESOURCE_TRACE_END] tracker_available=%u processor_available=%u metadata_only=1 unchanged_rejection=1\n",
		             g_gpu_memory != nullptr ? 1u : 0u, cp != nullptr ? 1u : 0u);
		std::fflush(stderr);
		return;
	}
	g_gpu_memory->TraceEopResources(cp);
}

